const moveCmdbNativeKeys = `-- name: MoveCmdbNativeKeys :exec
UPDATE cmdb_ci_identifier d SET ci_id = $1
WHERE d.tenant_id = current_tenant_id() AND d.ci_id = $2 AND d.name LIKE 'source:%'
  AND NOT EXISTS (SELECT 1 FROM cmdb_ci_identifier s
                  WHERE s.tenant_id = d.tenant_id AND s.ci_id = $1 AND s.name = d.name)
`

type MoveCmdbNativeKeysParams struct {
	SurvivorID  pgtype.UUID
	DuplicateID pgtype.UUID
}

// A merged duplicate's own keys of its sources go to the survivor, so a rerun finds it.
func (q *Queries) MoveCmdbNativeKeys(ctx context.Context, arg MoveCmdbNativeKeysParams) error {
	_, err := q.db.Exec(ctx, moveCmdbNativeKeys, arg.SurvivorID, arg.DuplicateID)
	return err
}

const moveCmdbRelations = `-- name: MoveCmdbRelations :exec
UPDATE cmdb_relation r SET
  source_ci_id = CASE WHEN r.source_ci_id = $1 THEN $2 ELSE r.source_ci_id END,
  target_ci_id = CASE WHEN r.target_ci_id = $1 THEN $2 ELSE r.target_ci_id END
WHERE r.tenant_id = current_tenant_id()
  AND (r.source_ci_id = $1 OR r.target_ci_id = $1)
  AND NOT (r.source_ci_id = $2 OR r.target_ci_id = $2)
  AND NOT EXISTS (
    SELECT 1 FROM cmdb_relation s
    WHERE s.tenant_id = r.tenant_id AND s.type_key = r.type_key
      AND s.source_ci_id = CASE WHEN r.source_ci_id = $1 THEN $2 ELSE r.source_ci_id END
      AND s.target_ci_id = CASE WHEN r.target_ci_id = $1 THEN $2 ELSE r.target_ci_id END)
`

type MoveCmdbRelationsParams struct {
	DuplicateID pgtype.UUID
	SurvivorID  pgtype.UUID
}

// A merged duplicate's relations go to the survivor; one the survivor already has is dropped
// below, as is one that would join the survivor to itself.
func (q *Queries) MoveCmdbRelations(ctx context.Context, arg MoveCmdbRelationsParams) error {
	_, err := q.db.Exec(ctx, moveCmdbRelations, arg.DuplicateID, arg.SurvivorID)
	return err
}

