const walkCmdbImpact = `-- name: WalkCmdbImpact :many
WITH RECURSIVE walk(ci_id, depth, path) AS (
  SELECT $1::uuid, 0, ARRAY[$1::uuid]
  UNION ALL
  SELECT step.next_id, w.depth + 1, w.path || step.next_id
  FROM walk w
  CROSS JOIN LATERAL (
    SELECT r.source_ci_id AS next_id FROM cmdb_relation r
    WHERE r.tenant_id = current_tenant_id() AND $2::boolean
      AND r.target_ci_id = w.ci_id AND r.type_key = ANY($3::text[])
    UNION ALL
    SELECT r.target_ci_id FROM cmdb_relation r
    WHERE r.tenant_id = current_tenant_id() AND $2::boolean
      AND r.source_ci_id = w.ci_id AND r.type_key = ANY($4::text[])
    UNION ALL
    SELECT r.target_ci_id FROM cmdb_relation r
    WHERE r.tenant_id = current_tenant_id() AND NOT $2::boolean
      AND r.source_ci_id = w.ci_id AND r.type_key = ANY($3::text[])
    UNION ALL
    SELECT r.source_ci_id FROM cmdb_relation r
    WHERE r.tenant_id = current_tenant_id() AND NOT $2::boolean
      AND r.target_ci_id = w.ci_id AND r.type_key = ANY($4::text[])
  ) step
  WHERE w.depth < $5::int AND NOT step.next_id = ANY(w.path)
)
SELECT ci_id, min(depth)::int AS depth FROM walk WHERE depth > 0
GROUP BY ci_id ORDER BY 2, 1
LIMIT 2000
`

type WalkCmdbImpactParams struct {
	CiID          pgtype.UUID
	Downstream    bool
	SourceSuffers []string
	TargetSuffers []string
	MaxDepth      int32
}

type WalkCmdbImpactRow struct {
	CiID  pgtype.UUID
	Depth int32
}

// The CIs an impact reaches from one CI, each at its nearest depth: downstream, those that suffer
// when it fails; upstream, those whose failure it suffers. Which types carry impact which way is
// bound by the application (the catalogue's `impact`); the walk never revisits a CI on its path.
func (q *Queries) WalkCmdbImpact(ctx context.Context, arg WalkCmdbImpactParams) ([]WalkCmdbImpactRow, error) {
	rows, err := q.db.Query(ctx, walkCmdbImpact,
		arg.CiID,
		arg.Downstream,
		arg.SourceSuffers,
		arg.TargetSuffers,
		arg.MaxDepth,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WalkCmdbImpactRow{}
	for rows.Next() {
		var i WalkCmdbImpactRow
		if err := rows.Scan(&i.CiID, &i.Depth); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
